-- 117 | 2026-11-21 | Tiền Giang cũ, wave 3/3, TX Cai Lậy + huyện Cai Lậy + huyện Cái Bè.
-- This is a list of researched *prospects* (NOT visits or approved active customers).
-- Preserve pre-merger old district boundaries, esp. Bình Phú/Phú An/Phú Nhuận/Ngũ Hiệp/Mỹ Long = Huyện Cai Lậy;
-- streets 30/4, Nguyễn Văn Lo, Mỹ Trang = TX Cai Lậy; Cái Bè is a different district.
-- Do not duplicate existing official NS Lam Phượng and Thành Trang in Cái Bè. 
-- Suppress co-located Hồng Hà Lam Phương and mapped Nhà sách Lam Phương; single record with alias/phone note.
-- Wholesale or tax-only entities need field confirmation, no invented GPS/checkins/photos/is_selling.
WITH src AS (
 SELECT x.*, md5('fbmn:tiengiang-old:wave03:'||x.source_key) AS dg
 FROM jsonb_to_recordset('[{"district":"Thị xã Cai Lậy","name":"Nhà sách FAHASA Cai Lậy","address_line":"Lầu 1 Co.opmart Cai Lậy, 79 đường 30 Tháng 4, khu phố 2, phường 1 cũ, TX Cai Lậy","category":"nha_sach","phone":"02733710266","tax_code":"0304132047118","source_key":"gmap:ChIJE1X5ghWXCjERm-5svef_sSc","source_url":"https://www.google.com/maps/search/?api=1&query=FAHASA%20Cai%20L%E1%BA%ADy%20Co.opmart%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJE1X5ghWXCjERm-5svef_sSc","verification_note":"FAHASA chính thức xác nhận địa điểm; số đăng ký chi nhánh 0304132047-118. Không tạo thêm điểm Co.opmart tầng 2 do nguồn đối tác ghi khác tầng."},{"district":"Thị xã Cai Lậy","name":"Nhà sách Khai Trí","address_line":"02 Nguyễn Văn Lo, phường 1 cũ, TX Cai Lậy","category":"nha_sach","phone":"0982827313","tax_code":null,"source_key":"gmap:ChIJOVm0tLyXCjERgujmGiMOeds","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Khai%20Tr%C3%AD%2002%20Nguy%E1%BB%85n%20V%C4%83n%20Lo%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJOVm0tLyXCjERgujmGiMOeds","verification_note":"Nguồn Maps và Sổ Tay Vàng xác nhận số nhà, chưa ghé."},{"district":"Thị xã Cai Lậy","name":"Nhà sách TBTH Hùng Vương Cai Lậy","address_line":"2-4-6-8 Đặng Văn Thạnh, TX Cai Lậy cũ","category":"nha_sach","phone":null,"tax_code":null,"source_key":"thienlong:cailey:hungvuong:2468-dvt","source_url":"https://thienlonggroup.com/news/soi-noi-cac-hoat-dong-ho-tro-ban-hang-mua-tuu-truong-cua-thien-long","verification_note":"Danh sách chương trình Thiên Long năm 2019; chưa xác minh còn hoạt động hay đã đổi địa chỉ/biển hiệu."},{"district":"Thị xã Cai Lậy","name":"Bí Bo - Photocopy và VPP","address_line":"Đường Mỹ Trang, khu phố 1, phường 4 cũ, TX Cai Lậy","category":"van_phong_pham","phone":"02733710077","tax_code":null,"source_key":"gmap:ChIJPXsQwL2XCjERh_XNLgZJnmY","source_url":"https://www.google.com/maps/search/?api=1&query=B%C3%AD%20Bo%20photocopy%20v%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Cai%20L%E1%BA%A