ery=Nh%C3%A0%20s%C3%A1ch%20Nga%20%C4%90H71%20C%C3%A1i%20B%C3%A8%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJ2dS48MSaCjER9QZ77kt2J_Q","verification_note":"Không có số nhà và số điện thoại, vị trí từ Google Maps, cần xác minh xã cũ."},{"district":"Huyện Cái Bè","name":"Văn phòng phẩm - photocopy Mỹ Quới","address_line":"Ấp Mỹ Quới, xã Mỹ Đức Đông cũ, huyện Cái Bè","category":"van_phong_pham","phone":"0907598078","tax_code":null,"source_key":"gmap:ChIJkbNLpkOFCjERt5iBDyKW7Yo","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20photocopy%20%E1%BA%A5p%20M%E1%BB%B9%20Qu%E1%BB%9Bi%20M%E1%BB%B9%20%C4%90%E1%BB%A9c%20T%C3%A2y%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJkbNLpkOFCjERt5iBDyKW7Yo","verification_note":"Địa danh mới Mỹ Đức Tây gồm địa bàn xã Mỹ Đức Đông cũ; cần xác minh xã cũ và địa điểm mặt tiền."},{"district":"Huyện Cái Bè","name":"Văn phòng phẩm Kim Dung","address_line":"Quốc lộ 1A, khu vực Mỹ Đức Tây cũ, huyện Cái Bè (Plus Code 8WVH+F2G)","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"gmap:ChIJV2GhSYyFCjERKcPr9MDwH6E","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Kim%20Dung%20M%E1%BB%B9%20%C4%90%E1%BB%A9c%20T%C3%A2y%20C%C3%A1i%20B%C3%A8%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJV2GhSYyFCjERKcPr9MDwH6E","verification_note":"Điểm Maps không có số nhà/điện thoại, cần Sales xác minh."},{"district":"Huyện Cái Bè","name":"Văn phòng phẩm Thúy Hiền","address_line":"Quốc lộ 1A, khu vực Mỹ Đức Tây cũ, huyện Cái Bè (Plus Code 8WVJ+83J)","category":"van_phong_pham","phone":"0939375755","tax_code":null,"source_key":"gmap:ChIJU0NWzvuECjERfUylwX1gbNE","source_url":"https://www.google.com/maps/search/?api=1&query=VPP%20Th%C3%BAy%20Hi%E1%BB%81n%20Qu%E1%BB%91c%20l%E1%BB%99%201A%20M%E1%BB%B9%20%C4%90%E1%BB%A9c%20T%C3%A2y%20Ti%E1%BB%81n%20Giang&query_place_id=ChIJU0NWzvuECjERfUylwX1gbNE","verification_note":"Mã plus-code cạnh điểm Kim Dung, Place ID khác; phải xác minh có hai cửa hàng độc lập."},{"district":"Huyện Cái Bè","name":"Hộ kinh doanh Nhà sách - VPP P. Cái Bè","address_line":"Ấp 3, xã Cái Bè hiện hành (thuộc huyện Cái Bè cũ, chưa có số nhà)","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"dauthau:vnz000052176:pcai-be","source_url":"https://dauthau.asia/en/project-owner/listlocation/X-Xa-Cai-Be-moi-28360/","verification_note":"Hồ sơ nhà thầu 2026 có tên Nhà sách/VPP P.Cái Bè, địa chỉ mới Ấp 3; CHƯA rõ có quầy bán lẻ và có trùng Nhà sách Cái Bè khu 4 hay không."},{"district":"Huyện Cái Bè","name":"Công ty Tâm Bảo Tín (dịch vụ photo, có ngành sách-VPP)","address_line":"Ấp 1, xã An Hữu cũ, huyện Cái Bè","category":"van_phong_pham","phone":null,"tax_code":"1201661315","source_key":"tax:1201661315:tambaotin-anhou","source_url":"https://infodoanhnghiep.com/thong-tin/Cong-Ty-Trách-Nhiệm-Hữu-Hạn-Mot-Thanh-Vien-Thuong-Mai-Dich-Vu-Tam-Bao-Tin-61315.html","verification_note":"Ngành chính là dịch vụ photocopy, có ngành đăng ký bán sách/VPP; CHƯA xác minh cửa hàng bán lẻ có thật; cần ưu tiên gọi trước."}]'::jsonb) AS x(
  district text,name text,address_line text,category text,phone text,tax_code text,
  source_key text,source_url text,verification_note text)
), ins AS (
 INSERT INTO public.field_prospects (
  id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,
  note,status,source_kind,research_source_key,research_source_url,research_batch
 )
 SELECT
  (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)
    ||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
  NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
  s.name,s.address_line,'Tiền Giang',s.district,s.category,s.phone,s.tax_code,
  'Nguồn công khai nghiên cứu 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác nhận thực địa. '||
   s.verification_note||' Nguồn: '||s.source_url,
  'new','manual',s.source_key,s.source_url,'2026-11-21-tien-giang-old-wave-03-three-districts'
 FROM src s
 WHERE s.district IN ('Thị xã Cai Lậy','Huyện Cai Lậy','Huyện Cái Bè')
 AND s.source_url LIKE 'https://%'
 AND NOT EXISTS (
  SELECT 1 FROM public.customers c
  WHERE c.province='Tiền Giang' AND c.district=s.district
  AND lower(btrim(c.name))=lower(btrim(s.name))
 )
 AND NOT EXISTS (
  SELECT 1 FROM public.field_prospects p
  WHERE p.province='Tiền Giang' AND p.district=s.district
  AND (p.research_source_key=s.source_key OR
       (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line))))
 )
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,category,phone,tax_code
)
SELECT district,count(*)::int inserted,
 count(*) FILTER (WHERE category='nha_sach')::int bookstores,
 count(*) FILTER (WHERE category='van_phong_pham')::int stationery,
 count(*) FILTER (WHERE phone IS NOT NULL)::int phones,
 count(*) FILTER (WHERE tax_code IS NOT NULL)::int tax_codes
 FROM ins GROUP BY district ORDER BY district;